// Claims (part 21.06): the register of claim events (a delay, a hindrance, an instruction, a rejected variation, a suspension) with the time-bar of the notice; the claim with its entitlement, the notice (a letter of 11.05 served within the time-bar), the quantum build-up
// from calculation templates, an evidence pack of immutable snapshots assembled from the records of the project, the submission, negotiation and determination log, the extension of time awarded (the revised completion date of the contract, 21.01) and the disputes register.
// Money is paise inside and rupees in the API.
for (const [key, type, def, description, min, max] of [
  ['ctr.claim.alert_days', 'string', '14,7,3,1', 'Days before the time-bar of a notice that its owners are told, separated by commas (part 21.06 BR-01).', null, null],
  ['ctr.claim.default_time_bar_days', 'integer', 28, 'Days from the event to the notice when the contract has no time-bar clause.', 1, 365],
  ['ctr.claim.escalate_days', 'integer', 3, 'Within this many days of the time-bar (or after it) the alert goes to the commercial manager and the project director.', 0, 60]]) {
  if (!parameterRegistry.get(key)) parameterRegistry.define({ key, dataType: type, default: def, scopes: ['system', 'company'], description, ...(min == null ? {} : { min, max }) });
}
export const CLAIM_TYPE = { EOT: 'Extension of time', COST: 'Cost', BOTH: 'Time and cost' };
export const CLAIM_STATE = { PREPARING: 'Being prepared', READY: 'Approved, ready to submit', SUBMITTED: 'Submitted', NEGOTIATION: 'In negotiation', DETERMINED: 'Determined', CLOSED: 'Closed', WITHDRAWN: 'Withdrawn' };
export const BAR_STATUS = { OPEN: 'Notice due', SERVED: 'Notice served in time', LAPSED: 'Time-bar passed', WAIVED: 'Waived' };
export const HEAD_LABEL = { DIRECT: 'Direct cost', PROLONGATION: 'Prolongation (site overheads)', IDLE_LABOUR: 'Idle labour', IDLE_PLANT: 'Idle plant', DISRUPTION: 'Disruption', FINANCE: 'Finance cost', ESCALATION: 'Escalation', PROFIT: 'Profit and overheads' };
export const FORUM = { ENGINEER: 'Engineer decision', DAB: 'Dispute board', ADJUDICATION: 'Adjudication', ARBITRATION: 'Arbitration', COURT: 'Court', AMICABLE: 'Amicable settlement' };
const rs = (p) => (p == null ? null : Math.round(p) / 100); const paise = (r) => Math.round(Number(r) * 100);
const addDays = (iso, n) => new Date(Date.parse(`${iso}T00:00:00Z`) + n * 86_400_000).toISOString().slice(0, 10); const dayDiff = (a, b) => Math.round((Date.parse(`${a}T00:00:00Z`) - Date.parse(`${b}T00:00:00Z`)) / 86_400_000);
const BASE_HEADS = ['DIRECT', 'PROLONGATION', 'IDLE_LABOUR', 'IDLE_PLANT', 'DISRUPTION'];
/** T-01 / FR-04: the amount (paise) of a quantum head from its inputs in rupees: prolongation is the site overhead per day times the days; profit is a percent of the base. */
export function quantumAmount(head, inputs, baseTotalPaise = 0) {
  const n = (k) => Number(inputs[k] ?? 0); const need = (...ks) => { for (const k of ks) if (!(k in inputs)) throw unprocessable(`${HEAD_LABEL[head]}: give ${k}`); };
  switch (head) {
    case 'DIRECT': case 'DISRUPTION': need('amount'); return paise(n('amount'));
    case 'PROLONGATION': need('perDay', 'days'); return Math.round(paise(n('perDay')) * n('days'));
    case 'IDLE_LABOUR': need('headcount', 'days', 'dailyRate'); return Math.round(paise(n('dailyRate')) * n('headcount') * n('days'));
    case 'IDLE_PLANT': need('units', 'days', 'dailyRate'); return Math.round(paise(n('dailyRate')) * n('units') * n('days'));
    case 'FINANCE': need('principal', 'annualPct', 'days'); return Math.round((paise(n('principal')) * n('annualPct') * n('days')) / 36500);
    case 'ESCALATION': need('base', 'pct'); return Math.round((paise(n('base')) * n('pct')) / 100);
    case 'PROFIT': need('pct'); return Math.round((baseTotalPaise * n('pct')) / 100);
    default: throw unprocessable('Unknown head.');
  }
}

