    remove: (actor, id) => flow.remove(actor, id), submit(actor, id) { flow.submit(actor, id); return claims.get(actor, id); }, withdraw: (actor, id, b) => { flow.withdraw(actor, id, b); return claims.get(actor, id); }, cancel: (actor, id, b) => { flow.cancel(actor, id, b); return claims.get(actor, id); }, history: (actor, id) => flow.history(actor, id),
